SELECT COUNT(*) FROM ( SELECT a.bbs_id , a.sr_no , a.req_type , a.process_type , a.req_channel , a.bbs_ttl , a.bbs_cn , a.process_state , a.process_cn , IFNULL(a.inq_cnt, 0) as inq_cnt , a.frst_crt_id as reqManagerId , m1.user_name as reqManagerNm , a.process_manager_id , m2.user_name AS processManagerNm , a.urgent_yn , a.frst_crt_id , a.frst_crt_dt , a.last_mdfcn_id , a.last_mdfcn_dt , a.use_yn FROM G_SR_MAINTENANCE AS a LEFT JOIN op_manager AS m1 on a.frst_crt_id = m1.user_id LEFT JOIN op_manager AS m2 on a.process_manager_id = m2.user_id WHERE 1=1
AND DATE_FORMAT(a.frst_crt_dt, '%Y%m%d') BETWEEN #{startDt} AND #{endDt}
AND sr_no LIKE CONCAT('%', #{query}, '%')
AND bbs_ttl LIKE CONCAT('%', #{query}, '%')
AND bbs_cn LIKE CONCAT('%', #{query}, '%')
AND ( sr_no LIKE CONCAT('%', #{query}, '%') OR bbs_ttl LIKE CONCAT('%', #{query}, '%') OR bbs_cn LIKE CONCAT('%', #{query}, '%') )
AND a.process_state IN (
#{item}
)
AND a.use_yn = 'Y' )

SELECT a.bbs_id , a.sr_no , a.req_type , a.process_type , a.req_channel , a.bbs_ttl , a.bbs_cn , a.process_state , a.process_cn as process_cn , IFNULL(a.inq_cnt, 0) as inq_cnt , a.frst_crt_id as reqManagerId , a.reqManagerNm AS reqManagerNm , a.process_manager_id , a.process_Manager_Nm AS processManagerNm , a.urgent_yn , a.frst_crt_id , a.frst_crt_dt , a.last_mdfcn_id , a.last_mdfcn_dt , a.process_start_date , a.process_end_date , a.use_yn , (select count(*) from G_SR_MAINTENANCE_file where use_yn = 'Y' and bbs_id = a.bbs_id) as attachedFileCnt , a.reqTypeNm , a.reqChannelNm , a.processTypeNm , a.processStateNm FROM ( SELECT a.bbs_id , a.sr_no , a.req_type , a.process_type , a.req_channel , a.bbs_ttl , a.bbs_cn , a.process_state , a.process_cn , IFNULL(a.inq_cnt, 0) as inq_cnt , a.frst_crt_id as reqManagerId , m1.user_name as reqManagerNm , a.process_manager_id , a.process_Manager_Nm , a.urgent_yn , a.frst_crt_id , a.frst_crt_dt , a.last_mdfcn_id , a.last_mdfcn_dt , a.process_start_date , a.process_end_date , a.use_yn , c1.label as reqTypeNm , c2.label as reqChannelNm , c3.label as processTypeNm , c4.label as processStateNm FROM G_SR_MAINTENANCE AS a LEFT JOIN op_manager AS m1 on a.frst_crt_id = m1.user_id LEFT JOIN op_manager AS m2 on a.process_manager_id = m2.user_id LEFT JOIN op_common_code AS c1 on a.req_type = c1.id AND c1.CODE_TYPE = 'MAINTEN_CATE_CODE' LEFT JOIN op_common_code AS c2 on a.req_channel = c2.id AND c2.CODE_TYPE = 'MAINTEN_PATH_CODE' LEFT JOIN op_common_code AS c3 on a.process_type = c3.id AND c3.CODE_TYPE = 'MAINTEN_PROC_CODE' LEFT JOIN op_common_code AS c4 on a.process_state = c4.id AND c4.CODE_TYPE = 'MAINTEN_STATE_CODE' WHERE 1=1
AND DATE_FORMAT(a.frst_crt_dt, '%Y%m%d') BETWEEN #{startDt} AND #{endDt}
AND sr_no LIKE CONCAT('%', #{query}, '%')
AND bbs_ttl LIKE CONCAT('%', #{query}, '%')
AND bbs_cn LIKE CONCAT('%', #{query}, '%')
AND ( sr_no LIKE CONCAT('%', #{query}, '%') OR bbs_ttl LIKE CONCAT('%', #{query}, '%') OR bbs_cn LIKE CONCAT('%', #{query}, '%') )
AND a.process_state IN (
#{item}
)
AND a.use_yn = 'Y' ORDER BY a.urgent_yn DESC, a.frst_crt_dt DESC ) a

mapper.insert:
INSERT INTO
	G_SR_MAINTENANCE
	(
		SR_NO
		, KI_TYPE
		, REQ_CHANNEL
		, REQ_TYPE
		, PROCESS_TYPE
		, PROCESS_STATE
		, REQ_USER_PHONE_NUMBER
		, REQ_USER_INFO
		, REQ_CRT_DATE
		, BBS_TTL
		, BBS_CN
		, PROCESS_CN
		, PROCESS_MANAGER_NM
		, PROCESS_RECEIPT_DATE
		, PROCESS_TARGET_END_DATE
		, PROCESS_START_DATE
		, PROCESS_END_DATE
		, FRST_CRT_ID
		, FRST_CRT_DT
	)
VALUES
	(
		(SELECT CONCAT('GGSR-', DATE_FORMAT(NOW(), '%y'), '-', IFNULL(SUBSTRING_INDEX(MAX(sr_no),'-',-1),0) + 1) AS SR_NO
			FROM G_SR_MAINTENANCE
			WHERE SR_NO like CONCAT('GGSR-', DATE_FORMAT(NOW(),'%y'), '-%'))
		, #{kiType}
		, #{reqChannel}
		, #{reqType}
		, #{processType}
		, #{processState}
		, #{reqUserPhoneNumber}
		, #{reqUserInfo}
		, DATE_FORMAT(SYSDATE,'%Y%m%d')
		, #{bbsTtl}
		, #{bbsCn}
		, #{processCn}
		, #{processManagerNm}
		, #{processReceiptDate}
		, #{processTargetEndDate}
		, #{processStartDate}
		, #{processEndDate}
		, #{frstCrtId}
		, NOW()
	)

INSERT INTO
	G_SR_MAINTENANCE_FILE
	(
		BBS_ID
		, ORGNL_ATCH_FILE_NM
		, ATCH_FILE_NM
		, ATCH_FILE_EXTN_NM
		, ATCH_FILE_SZ
		, ATCH_FILE_SEQ
		, ATCH_FILE_PATH_NM
		, FRST_CRT_ID
		, FRST_CRT_DT
	)
VALUES
	(
		#{bbsId}
		, #{orgnlAtchFileNm}
		, #{atchFileNm}
		, #{atchFileExtnNm}
		, #{atchFileSz}
		, (SELECT IFNULL(MAX(ATCH_FILE_SEQ)+1, 1) FROM G_SR_MAINTENANCE_FILE WHERE BBS_ID = #{bbsId})
		, #{atchFilePathNm}
		, #{frstCrtId}
		, NOW()
	)

mapper.update:
/**cmnty-mapper.deleteMaintenanceFileByFileId */
UPDATE
	G_SR_MAINTENANCE_FILE
SET
	USE_YN = 'N'
	, LAST_MDFCN_ID = #{lastMdfcnId}
	, LAST_MDFCN_DT = NOW()
WHERE
	FILE_ID = #{fileId}

/**cmnty-mapper.updateMaintenance */
UPDATE
	G_SR_MAINTENANCE
SET
	KI_TYPE = #{kiType}
	, REQ_CHANNEL = #{reqChannel}
	, REQ_TYPE = #{reqType}
	, PROCESS_TYPE = #{processType}
	, PROCESS_STATE = #{processState}
	, REQ_USER_PHONE_NUMBER = #{reqUserPhoneNumber}
	, REQ_USER_INFO = #{reqUserInfo}
	, BBS_TTL = #{bbsTtl}
	, BBS_CN = #{bbsCn}
	, PROCESS_MANAGER_NM = #{processManagerNm}
	, PROCESS_CN = #{processCn}
	, PROCESS_RECEIPT_DATE = #{processReceiptDate}
	, PROCESS_TARGET_END_DATE = #{processTargetEndDate}
	, PROCESS_START_DATE = #{processStartDate}
	, PROCESS_END_DATE = #{processEndDate}
	, LAST_MDFCN_ID = #{lastMdfcnId}
	, LAST_MDFCN_DT = NOW()
WHERE
	BBS_ID = #{bbsId}

/**cmnty-mapper.deleteMaintenance */
	UPDATE
		G_SR_MAINTENANCE
	SET
		USE_YN = 'N'
		, LAST_MDFCN_ID = #{lastMdfcnId}
		, LAST_MDFCN_DT = NOW()
	WHERE
		BBS_ID = #{bbsId}
